        case 'A': return 1; case 'C': return 2; case 'G': return 4; case 'T': return 8;
        case 'R': return 5; case 'Y': return 10; case 'S': return 6; case 'W': return 9;
        case 'K': return 12; case 'M': return 3; case 'B': return 14; case 'D': return 13;
        case 'H': return 11; case 'V': return 7; default: return 15;
    }
}
inline int nalleles(int n) { return __builtin_popcount((unsigned)n); }
inline char complement(char c) {
    const string bases = "ACGTRYMKSWBDHVNUacgtrymkswbdhvnu";
    const string comps = "TGCAYRKMSWVHDBNAtgcayrkmswvhdbna";
    size_t i = bases.find(c);
    return i == string::npos ? c : comps[i];
}
inline void reverse_complement(string& s) {
    std::reverse(s.begin(),s.end());
    for (char& c : s) c = complement(c);
}
inline void wrapped(std::ostream& out, const string& s, unsigned width, bool blank = true) {
    if (width == 0 || width == UINT32_MAX) {
        if (blank || !s.empty()) out << s << '\n';
    } else {
        for (size_t i = 0; i < s.size(); i += width) out.write(s.data()+i, std::min<size_t>(width,s.size()-i)) << '\n';
    }
}
inline void print_record(const Record& r, unsigned width = 0, std::ostream& out = std::cout, int force = 0) {
    bool fq = force ? force > 0 : !r.qual.empty();
    out << (fq ? '@' : '>') << r.name;
    if (!r.comment.empty()) out << ' ' << r.comment;
    out << '\n';
    wrapped(out,r.seq,width);
    if (fq) { out << "+\n"; wrapped(out,r.qual,width); }
}
inline void print_fasta(const string& name, const string& seq, unsigned width = 60) {
    std::cout << '>' << name << '\n';
    wrapped(std::cout, seq, width, false);
}
inline long long integer(const char* s) { return std::strtoll(s,nullptr,10); }
inline double real(const char* s) { return std::strtod(s,nullptr); }
inline double draw(std::mt19937_64& rng) { return (rng() >> 11) * 0x1p-53; }

struct Region { long long begin = 0, end = INT32_MAX; bool whole = true, reverse = false; };
using Regions = std::unordered_map<string,vector<Region>>;
inline bool load_regions(const string& file, Regions& regions, bool strand = false) {
    string data;
    if (!read_bytes(file,data)) return false;
    std::istringstream in(data);
    string line;
    while (std::getline(in,line)) {
        if (!line.empty() && line.back() == '\r') line.pop_back();
        if (line.empty()) continue;
        vector<string> parts;
        if (strand) {
            size_t a = 0, b;
            do { b = line.find('\t',a); parts.push_back(line.substr(a,b-a)); a=b+1; } while (b != string::npos);
        } else {
            std::istringstream row(line); string word;
            while(row >> word) parts.push_back(word);
        }
        if (parts.empty()) continue;
        Region r;
        if (parts.size() >= 3) {
            r.begin = integer(parts[1].c_str()); r.end = integer(parts[2].c_str()); r.whole = false;
        } else if (parts.size() == 2) {
            r.end = integer(parts[1].c_str()); r.begin = r.end-1; r.whole = false;
        }
        if (r.begin < 0) { r.begin=0; r.end=INT32_MAX; r.whole=true; }
        if (parts.size() >= 6) r.reverse = parts[5] == "-";
        regions[parts[0]].push_back(r);
    }
    return true;
}
