            }
        }
        r.seq=r.seq.substr((size_t)begin,(size_t)std::max(0LL,end-begin));
        if(fq)r.qual=r.qual.substr((size_t)begin,(size_t)std::max(0LL,end-begin));
        print_record(r,0,std::cout,fq?1:-1);
    }
    return 0;
}

