int sequence_command(int argc, char** argv) {
    int qlo=0, qhi=255, qshift=33, minlen=0;
    unsigned width=0; uint64_t seed=11; double fraction=1.0;
    char mask=0, fake=0;
    bool rev=false, both=false, fasta=false, comments=true, unambig=false, odd=false, even=false;
    bool shift=false, caps=false, mask_lower=false, strip=false, invert=false;
    string bed;
    int c;
    while ((c=getopt(argc,argv,"q:X:n:l:Q:s:f:M:L:F:crRaACN12VUxS"))>=0) {
        switch(c) {
            case 'q':qlo=(int)integer(optarg);break;
            case 'X':qhi=(int)integer(optarg);break;
            case 'n':mask=*optarg;break;
            case 'l':width=(unsigned)integer(optarg);break;
            case 'Q':qshift=(int)integer(optarg);break;
            case 's':seed=integer(optarg);break;
            case 'f':fraction=real(optarg);break;
            case 'M':bed=optarg;break;
            case 'L':minlen=(int)integer(optarg);break;
            case 'F':fake=*optarg;break;
            case 'c':invert=true;break;
            case 'r':rev=true;break;
            case 'R':both=true;break;
            case 'a':case 'A':fasta=true;break;
            case 'C':comments=false;break;
            case 'N':unambig=true;break;
            case '1':odd=true;break;
            case '2':even=true;break;
            case 'V':shift=true;break;
            case 'U':caps=true;break;
            case 'x':mask_lower=true;break;
            case 'S':strip=true;break;
        }
    }
    if (optind==argc && isatty(0)) return usage("seq");
    SequenceReader in(optind<argc?argv[optind]:"-");
    if (!in.good) return open_error("seq");
    Regions regions; bool has_bed=!bed.empty() && load_regions(bed,regions);
    std::mt19937_64 rng(seed);
    Record r; long long index=0;
    auto mask_char=[&](char& b){ b=mask?mask:lower(b); };
    while(in.next(r)) {
        ++index;
        if (fraction<1.0 && draw(rng)>=fraction) continue;
        if ((odd && index%2==0) || (even && index%2==1)) continue;
        if ((long long)r.seq.size()<minlen) continue;
        if (strip) {
            size_t j=0;
            for (size_t i=0;i<r.seq.size();++i) if(!std::isspace((unsigned char)r.seq[i])) {
                r.seq[j]=r.seq[i]; if(!r.qual.empty()) r.qual[j]=r.qual[i]; ++j;
            }
        }
        if (!r.qual.empty() && qlo>0) {
            for(size_t i=0;i<r.seq.size();++i) {
                int quality=(unsigned char)r.qual[i]-qshift;
                if(quality<qlo || quality>qhi) mask_char(r.seq[i]);
            }
        }
        if (has_bed) {
            vector<bool> marked(r.seq.size(),false);
            auto it=regions.find(r.name);
            if(it!=regions.end()) for(const Region& b:it->second) {
                long long end=std::min<long long>(b.end,r.seq.size());
                for(long long i=std::max(0LL,b.begin);i<end;++i) marked[(size_t)i]=true;
            }
            for(size_t i=0;i<r.seq.size();++i) if(marked[i]!=invert) mask_char(r.seq[i]);
        }
        if(caps) for(char& b:r.seq) b=upper(b);
        if(mask_lower) for(char& b:r.seq) if(std::islower((unsigned char)b)) mask_char(b);
        if(unambig && std::any_of(r.seq.begin(),r.seq.end(),[](char b){return nt4(b)==4;})) continue;
        if(shift) for(char& b:r.qual) b=(char)((unsigned char)b+33-qshift);
        if(fake) r.qual.assign(r.seq.size(),fake);
        if(fasta) r.qual.clear();
        if(!comments) r.comment.clear();
        if(both) {
            string name=r.name;
            r.name=name+"+"; print_record(r,width);
            reverse_complement(r.seq); std::reverse(r.qual.begin(),r.qual.end());
            r.name=name+"-"; print_record(r,width);
        } else {
            if(rev){reverse_complement(r.seq);std::reverse(r.qual.begin(),r.qual.end());}
            print_record(r,width);
        }
    }
    return 0;
}

int composition_command(int argc,char** argv) {
    bool caps=false; string bed; int c;
    while((c=getopt(argc,argv,"ur:"))>=0) {if(c=='u')caps=true;else if(c=='r')bed=optarg;}
    if(optind==argc && isatty(0))return usage("comp");
    SequenceReader in(optind<argc?argv[optind]:"-"); if(!in.good)return open_error("comp");
    Regions regions; bool restricted=!bed.empty() && load_regions(bed,regions);
    Record r;
    auto count=[&](long long begin,long long end) {
        std::array<long long,11> cnt{};
        for(long long i=std::max(0LL,begin);i<end;++i) {
            char ch=i<(long long)r.seq.size()?r.seq[(size_t)i]:'\0';
            if(caps && !std::isupper((unsigned char)ch))continue;
            int code=nt16(ch), n=nalleles(code), base=nt4(ch);
            if(n==1)++cnt[base];else if(n==2)++cnt[4];else if(n==3)++cnt[5];else ++cnt[6];
            if(n==2) { if(code==5 || code==10) ++cnt[9];else ++cnt[8]; }
            bool cpg=false;
            int prev=i>0 && i-1<(long long)r.seq.size()?nt16(r.seq[(size_t)i-1]):15;
            int next=i+1<(long long)r.seq.size()?nt16(r.seq[(size_t)i+1]):15;
            if((code==2 || code==10) && (next==4 || next==5))cpg=true;
            if((code==4 || code==5) && (prev==2 || prev==10))cpg=true;
            if(cpg){++cnt[7];if(code==5 || code==10)++cnt[10];}
        }
        std::cout<<r.name<<'\t';
        if(restricted)std::cout<<begin<<'\t'<<end;
        else std::cout<<r.seq.size();
        for(auto x:cnt)std::cout<<'\t'<<x;
        std::cout<<'\n';
    };
    while(in.next(r)) {
        if(!restricted) count(0,(long long)r.seq.size());
        else {
            auto it=regions.find(r.name);
            if(it!=regions.end())for(const auto& b:it->second) {
                if(b.end>1000000000){std::raise(SIGSEGV);return 139;}
                count(b.begin,b.end);
            }
        }
    }
    return 0;
}

int sample_command(int argc,char** argv) {
    uint64_t seed=11; bool twopass=false; int c;
    while((c=getopt(argc,argv,"2s:"))>=0){if(c=='s')seed=integer(optarg);else if(c=='2')twopass=true;}
    if(argc-optind<2)return usage("sample");
    string path=argv[optind]; double amount=real(argv[optind+1]);
    long long n=amount>=1.0?(long long)(amount+.499):0;
    if(n==0 && twopass){std::fputs("[W::stk_sample] when sampling a fraction, option -2 is ignored.",stderr);twopass=false;}
    if(twopass && path=="-"){std::fputs("[E::stk_sample] in the 2-pass mode, the input cannot be STDIN.\n",stderr);return 1;}
    SequenceReader in(path); if(!in.good)return open_error("sample");
    std::mt19937_64 rng(seed); Record r; long long seen=0;
    vector<std::pair<long long,Record>> reservoir;
    while(in.next(r)) {
        ++seen; double v=draw(rng);
        if(n==0) {if(v<amount)print_record(r);}
        else {
            long long k=seen<=n?seen-1:(long long)(v*seen);
            if(k<n) {
                if(k>=(long long)reservoir.size())reservoir.emplace_back(seen,r);
                else {
                    string old=reservoir[(size_t)k].second.comment;
                    reservoir[(size_t)k]={seen,r};
                    if(r.comment.empty())reservoir[(size_t)k].second.comment=old;
                }
            }
        }
    }
    if(n>0) {
        if(twopass) {
            std::sort(reservoir.begin(),reservoir.end(),[](const auto& a,const auto& b){return a.first<b.first;});
            SequenceReader again(path); long long i=0; size_t k=0;
            while(k<reservoir.size() && again.next(r)) {if(++i==reservoir[k].first){print_record(r);++k;}}
        } else for(const auto& x:reservoir)print_record(x.second);
    }
    return 0;
}

int subsequence_command(int argc,char** argv) {
    bool tab=false,strand=false; unsigned width=0; int c;
    while((c=getopt(argc,argv,"tsl:"))>=0){if(c=='t')tab=true;else if(c=='s')strand=true;else if(c=='l')width=(unsigned)integer(optarg);}
    if(argc-optind<2)return usage("subseq");
    Regions regions;
    if(!load_regions(argv[optind+1],regions,strand)) {
        std::fprintf(stderr,"[E::stk_subseq] failed to read the list of regions in file '%s'\n",argv[optind+1]);return 1;
    }
    SequenceReader in(argv[optind]);if(!in.good)return open_error("subseq");Record r;
    while(in.next(r)) {
        auto it=regions.find(r.name);if(it==regions.end())continue;
        for(const auto& b:it->second) {
            long long begin=b.begin, end=std::min<long long>(b.end,r.seq.size());
            if(begin>=(long long)r.seq.size()) {
                std::fprintf(stderr,"[subseq] %s: %lld >= %zu\n",r.name.c_str(),begin,r.seq.size());continue;
            }
            if(strand && end<begin){std::raise(SIGSEGV);return 139;}
            string seq=end>begin?r.seq.substr((size_t)begin,(size_t)(end-begin)):"";
            if(strand && b.reverse)reverse_complement(seq);
            if(tab) {
                std::cout<<r.name<<'\t'<<begin+1<<'\t';
                if(strand){std::cout<<'\n';wrapped(std::cout,seq,width,false);}
                else std::cout<<seq<<'\n';
            } else {
                std::cout<<(r.qual.empty()?'>':'@')<<r.name;
                if(!b.whole && b.end!=INT32_MAX)std::cout<<':'<<begin+1<<'-'<<end;
                if(!r.comment.empty())std::cout<<' '<<r.comment;
                std::cout<<'\n';wrapped(std::cout,seq,width,false);
                if(!strand && !r.qual.empty()) {
                    std::cout<<"+\n";
                    string q=end>begin?r.qual.substr((size_t)begin,(size_t)(end-begin)):"";
                    wrapped(std::cout,q,width,false);
                }
            }
        }
    }
    return 0;
}

int trim_command(int argc,char** argv) {
    double threshold=.05; long long minimum=30,left=0,right=0,maxlen=0; int c;
    while((c=getopt(argc,argv,"q:l:b:e:L:"))>=0) {
        switch(c){case 'q':threshold=real(optarg);break;case 'l':minimum=integer(optarg);break;case 'b':left=integer(optarg);break;case 'e':right=integer(optarg);break;case 'L':maxlen=integer(optarg);break;}
    }
    if(optind==argc)return usage("trimfq");
    SequenceReader in(argv[optind]);if(!in.good)return open_error("trimfq"); Record r;
    while(in.next(r)) {
        long long len=(long long)r.seq.size(), begin=0, end=len;
        bool fq=!r.qual.empty();
        if(left!=0 || right!=0 || maxlen!=0) {
            begin=std::min(len,std::max(0LL,left));end=std::max(begin,len-std::max(0LL,right));
            if(maxlen>0)end=std::min(end,begin+maxlen);
        } else if(fq && len>minimum) {
            vector<double> score((size_t)len);
            for(long long i=0;i<len;++i)score[(size_t)i]=threshold-std::pow(10.0,-.1*((unsigned char)r.qual[(size_t)i]-33));
            double total=0,best=0;long long start=0;begin=0;end=0;
            for(long long i=0;i<len;++i) {
                total+=score[(size_t)i];
                if(total>best){best=total;begin=start;end=i+1;}
                if(total<0){total=0;start=i+1;}
            }
            if(end-begin<minimum) {
                long long m=std::max(0LL,minimum);
                double sum=0;for(long long i=0;i<m;++i)sum+=score[(size_t)i];
                best=sum;begin=0;end=m;
                for(long long i=m;i<len;++i) {
                    sum+=score[(size_t)i]-score[(size_t)(i-m)];
                    if(sum>best+1e-12){best=sum;begin=i-m+1;end=i+1;}
                }
            }
        }
        r.seq=r.seq.substr((size_t)begin,(size_t)std::max(0LL,end-begin));
        if(fq)r.qual=r.qual.substr((size_t)begin,(size_t)std::max(0LL,end-begin));
        print_record(r,0,std::cout,fq?1:-1);
    }
    return 0;
}

struct QualityCounts {
    std::array<long long,5> bases{};
    std::array<long long,256> qualities{};
    long long n=0;
    void add(char b, unsigned char q){++bases[nt4(b)];++qualities[q];++n;}
};
int quality_command(int argc,char** argv) {
    int threshold=20,c;
    while((c=getopt(argc,argv,"q:"))>=0)if(c=='q')threshold=(int)integer(optarg);
    if(optind==argc)return usage("fqchk");
    SequenceReader in(argv[optind]);if(!in.good)return open_error("fqchk");
    Record r;vector<QualityCounts> positions;QualityCounts all;long long minimum=LLONG_MAX,maximum=0,reads=0;
    while(in.next(r)) {
        if(r.qual.empty())continue;
        ++reads;minimum=std::min<long long>(minimum,r.seq.size());maximum=std::max<long long>(maximum,r.seq.size());
        if(positions.size()<r.seq.size())positions.resize(r.seq.size());
        for(size_t i=0;i<r.seq.size();++i) {unsigned char q=(unsigned char)((unsigned char)r.qual[i]-33);positions[i].add(r.seq[i],q);all.add(r.seq[i],q);}
    }
    vector<int> qualities;for(int i=0;i<256;++i)if(all.qualities[i])qualities.push_back(i);
    double avglen=reads?(double)all.n/reads:-std::numeric_limits<double>::quiet_NaN();
    std::printf("min_len: %lld; max_len: %lld; avg_len: %.2f; %zu distinct quality values\n",minimum,maximum,avglen,qualities.size());
    std::printf("POS\t#bases\t%%A\t%%C\t%%G\t%%T\t%%N\tavgQ\terrQ");
    if(threshold)std::printf("\t%%low\t%%high");else for(int q:qualities)std::printf("\t%%Q%d",q);
    std::putchar('\n');
    auto row=[&](const QualityCounts& x) {
        std::printf("\t%lld",x.n);
        double nan=-std::numeric_limits<double>::quiet_NaN();
        for(long long b:x.bases)std::printf("\t%.1f",x.n?100.*b/x.n:nan);
        double sum=0,error=0;long long low=0;
        for(int q:qualities) {
            sum+=q*(double)x.qualities[q];
            double p=std::min(.5,std::max(1e-6,std::pow(10.,-.1*q)));
            error+=p*x.qualities[q];if(q<threshold)low+=x.qualities[q];
        }
        double eq=x.n?-10.*std::log10(error/x.n):-0.;
        std::printf("\t%.1f\t%.1f",x.n?sum/x.n:nan,eq);
        if(threshold)std::printf("\t%.1f\t%.1f",x.n?100.*low/x.n:nan,x.n?100.*(x.n-low)/x.n:nan);
        else for(int q:qualities)std::printf("\t%.2f",x.n?100.*x.qualities[q]/x.n:nan);
        std::putchar('\n');
    };
    std::printf("ALL");row(all);
    for(size_t i=0;i<positions.size();++i){std::printf("%zu",i+1);row(positions[i]);}
    return 0;
}

int simple_command(const string& cmd,int argc,char** argv) {
    if(argc<2 && (cmd=="randbase" || cmd=="listhet"))return usage(cmd);
    SequenceReader in(argc>1?argv[1]:"-");if(!in.good)return open_error(cmd);
    Record r;long long count=0,bases=0;
    while(in.next(r)) {
        if(cmd=="size"){++count;bases+=(long long)r.seq.size();}
        else if(cmd=="hpc") {
            string s;for(char c:r.seq)if(s.empty() || s.back()!=c)s+=c;
            if(!s.empty())print_fasta(r.name,s,0);
        } else if(cmd=="listhet") {
            for(size_t i=0;i<r.seq.size();++i)if(nalleles(nt16(r.seq[i]))==2)std::cout<<r.name<<'\t'<<i+1<<'\t'<<r.seq[i]<<'\n';
        } else if(cmd=="randbase") {
            for(char& c:r.seq) {
                int bits=nt16(c);if(nalleles(bits)!=2)continue;
                int lo=0,hi=0;for(int i=0;i<4;++i)if(bits&(1<<i)){hi=i;}
                for(int i=3;i>=0;--i)if(bits&(1<<i)){lo=i;}
                char b="ACGT"[drand48()<.5?hi:lo]; c=std::islower((unsigned char)c)?lower(b):b;
            }
            print_fasta(r.name,r.seq);
        }
    }
    if(cmd=="size")std::cout<<count<<'\t'<<bases<<'\n';
    return 0;
}

int gap_command(int argc,char** argv) {
    int length=50,c;while((c=getopt(argc,argv,"l:"))>=0)if(c=='l')length=(int)integer(optarg);
    if(optind==argc)return usage("gap");
    SequenceReader in(argv[optind]);if(!in.good)return open_error("gap");Record r;
    while(in.next(r))for(size_t i=0;i<r.seq.size();) {
        if(nt4(r.seq[i])<4){++i;continue;}
        size_t begin=i;while(i<r.seq.size() && nt4(r.seq[i])==4)++i;
        if((long long)(i-begin)>=length)std::cout<<r.name<<'\t'<<begin<<'\t'<<i<<'\n';
    }
    return 0;
}

int mutation_command(int argc,char** argv) {
    if(argc<3)return usage("mutfa");
    string mutations;if(!read_bytes(argv[2],mutations))return open_error("mutfa");
    SequenceReader in(argv[1]);if(!in.good)return open_error("mutfa");
    std::unordered_map<string,vector<std::pair<long long,char>>> changes;
    std::istringstream input(mutations);string line;
    while(std::getline(input,line)) {
        std::istringstream row(line);string name,at,from,to;
        if(!(row>>name>>at>>from>>to) || to.size()!=1 || !std::isalpha((unsigned char)to[0]))continue;
        changes[name].emplace_back(integer(at.c_str())-1,to[0]);
    }
    Record r;while(in.next(r)) {
        auto it=changes.find(r.name);if(it!=changes.end())for(auto p:it->second)if(p.first>=0 && p.first<(long long)r.seq.size())r.seq[(size_t)p.first]=p.second;
        print_fasta(r.name,r.seq);
    }
    return 0;
}

inline string pair_name(string name) {
    if(name.size()>=2 && name[name.size()-2]=='/' && (name.back()=='1' || name.back()=='2'))name.resize(name.size()-2);
    return name;
}
int pair_command(const string& cmd,int argc,char** argv) {
    SequenceReader in(argc>1?argv[1]:"-");if(!in.good)return open_error(cmd);
    string prefix=argc>2?argv[2]:"";long long index=1;
    Record r, pending;bool have=false;
    auto put=[&](Record rec){if(cmd=="rename")rec.name=prefix+std::to_string(index);print_record(rec);};
    auto cache=[&](const Record& src){string old=pending.comment;pending=src;if(src.comment.empty())pending.comment=old;};
    while(in.next(r)) {
        if(!have){cache(r);have=true;continue;}
        if(pair_name(pending.name)==pair_name(r.name)) {put(pending);put(r);++index;have=false;}
        else {if(cmd=="rename"){put(pending);++index;}cache(r);}
    }
    if(have && cmd=="rename")put(pending);
    return 0;
}

int interleave_command(int argc,char** argv) {
    if(argc<3)return usage("mergepe");
    SequenceReader in1(argv[1]),in2(argv[2]);if(!in1.good||!in2.good)return open_error("mergepe");
    Record a,b;
    while(true) {
        bool ra=in1.next(a),rb=in2.next(b);
        if(!ra || !rb) {
            if(ra)std::fputs("[W::stk_mergepe] the 2nd file has fewer records.\n",stderr);
            if(rb)std::fputs("[W::stk_mergepe] the 1st file has fewer records.\n",stderr);
            break;
        }
        print_record(a);print_record(b);
    }
    return 0;
}

int split_command(int argc,char** argv) {
    int n=10,c;unsigned width=0;
    while((c=getopt(argc,argv,"n:l:"))>=0){if(c=='n')n=(int)integer(optarg);else if(c=='l')width=(unsigned)integer(optarg);}
    if(argc-optind<2)return usage("split");
    SequenceReader in(argv[optind+1]);if(!in.good)return open_error("split");
    if(n<=0){std::raise(SIGFPE);return 136;}
    vector<std::unique_ptr<std::ofstream>> files;
    for(int i=0;i<n;++i) {
        char suffix[40];std::snprintf(suffix,sizeof suffix,".%05d.fa",i+1);
        auto out=std::make_unique<std::ofstream>(string(argv[optind])+suffix,std::ios::binary);
        if(!*out)return 1;files.push_back(std::move(out));
    }
    Record r;int i=0;while(in.next(r)){print_record(r,width,*files[(size_t)i]);i=(i+1)%n;}
    return 0;
}

int heterozygosity_command(int argc,char** argv) {
    long long window=50000,starts=5;bool mask=false;int c;
    while((c=getopt(argc,argv,"w:t:m"))>=0){if(c=='w')window=integer(optarg);else if(c=='t')starts=integer(optarg);else if(c=='m')mask=true;}
    if(optind==argc)return usage("hety");
    SequenceReader in(argv[optind]);if(!in.good)return open_error("hety");
    if(starts==0 || window/starts==0){std::raise(SIGFPE);return 136;}
    long long step=window/starts; Record r;
    while(in.next(r)) {
        vector<long long> effective(r.seq.size()+1),hetero(r.seq.size()+1);
        for(size_t i=0;i<r.seq.size();++i) {
            int n=nalleles(nt16(r.seq[i]));bool valid=!mask || !std::islower((unsigned char)r.seq[i]);
            effective[i+1]=effective[i]+(valid && n<=2);
            hetero[i+1]=hetero[i]+(valid && n==2);
        }
        long long last=0,len=(long long)r.seq.size();
        auto emit=[&](long long start,long long end,long long from) {
            long long n=effective[(size_t)end]-effective[(size_t)from],h=hetero[(size_t)end]-hetero[(size_t)from];
            if(n)std::printf("%s\t%lld\t%lld\t%.2f\t%lld\t%lld\n",r.name.c_str(),start,end,(double)window*h/n,n,h);
        };
        if(window>0 && step>0)for(long long end=window;end<len;end+=step){emit(last,end,end-window);last=end;}
        emit(last,len,last);
    }
    return 0;
}

