    while((c=getopt(argc,argv,"wf:l:x:"))>=0){if(c=='w')at=true;else if(c=='f')fraction=real(optarg);else if(c=='l')minimum=integer(optarg);else if(c=='x')drop=real(optarg);}
    if(optind==argc)return usage("gc");
