        string reversed=seq;reverse_complement(reversed);
        score=best=0;long long bestright=0;
        for(long long i=1;i<=len-left;++i) {
            if(scoring)std::cout<<"Q\t"<<r.name<<'\t'<<i<<'\t'<<score<<'\t'<<best<<'\n';
            if(best-score>=drop)break;
            if(m && i>=(long long)m) {
                bool match=rotations.count(reversed.substr((size_t)(i-m),m));
                score+=match?1:-penalty;
                if(score>best){best=score;bestright=i;}
